(function(){
  // TEST-BRANCH integration layer. No deployment has been performed.
  // Customer never sees internal stock-check wording.
  const U='https://bpnkouymdvcogeaqjmxl.supabase.co',K='sb_publishable_v6rJbF4IfGZTKtbuQtmsmQ_lS3sXWFa';
  const $=id=>document.getElementById(id);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let shownOrderId='',lastOutageKey=null;

  async function token(){try{const {data}=await sb.auth.getSession();return data.session?.access_token||''}catch{return''}}
  async function call(url,body){
    const t=await token();if(!t)throw Error('Please sign in again.');
    const r=await fetch(url,{method:'POST',headers:{apikey:K,Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify(body)});
    const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');return d;
  }
  const amendApi=body=>call(U+'/functions/v1/collection-order-amend-test-api',body);
  const orderApi=body=>call(U+'/functions/v1/collection-orders-api',body);

  async function outageIds(){
    try{const d=await amendApi({action:'daily_outages'});return new Set((d.item_ids||[]).map(String))}
    catch{return new Set()}
  }
  async function applyOutagesToCategories(list,blocked){
    blocked=blocked||await outageIds();
    for(const c of list||[])for(const i of c.items||[]){
      // Remember the menu's own stock state so a temporary daily outage can be removed
      // without incorrectly leaving the item unavailable until a full page reload.
      if(typeof i.__dextersBaseInStock==='undefined')i.__dextersBaseInStock=i.in_stock!==false;
      i.in_stock=!!i.__dextersBaseInStock&&!blocked.has(String(i.id));
    }
    return blocked;
  }
  async function applyOutages(){
    try{
      const blocked=await outageIds();
      const key=[...blocked].sort().join('|');
      if(key===lastOutageKey)return false;
      lastOutageKey=key;
      await applyOutagesToCategories(categories||[],blocked);
      renderMenu();
      return true;
    }catch{return false}
  }

  function ensureAlert(){
    if($('collectionAmendAlert'))return $('collectionAmendAlert');
    const host=$('msg')?.parentElement||document.body;
    const x=document.createElement('div');x.id='collectionAmendAlert';x.className='status bad hide';
    host.insertBefore(x,host.firstChild);return x;
  }

  function showAmend(order){
    const x=ensureAlert();shownOrderId=String(order.id||'');
    const blocked=new Set((order.amendment_items||[]).map(String));
    const names=(order.items||[]).filter(i=>blocked.has(String(i.id||''))).map(i=>String(i.base_name||i.name||'Item'));
    x.classList.remove('hide');
    x.innerHTML='<b>Sorry, you need to amend your order.</b><br>'+
      (names.length?'Unavailable: <b>'+names.map(esc).join(', ')+'</b><br>':'')+
      esc(order.amendment_note||'One or more items are unavailable today.')+
      '<br><button type="button" id="collectionStartAmendBtn" class="btn">Amend order</button>';
    $('collectionStartAmendBtn').onclick=()=>{
      try{
        window.DexterCollectionBasket.loadAmendment(order);
        x.innerHTML='<b>Amend your order</b><br>The unavailable item has been removed. Choose a replacement from the full Dexter’s menu, then tap <b>Send amended order</b>.';
        $('search')?.scrollIntoView({behavior:'smooth',block:'start'});$('search')?.focus();
      }catch(e){x.innerHTML='<b>Could not load the order.</b><br>'+esc(e.message)}
    };
  }

  async function poll(){
    try{
      const d=await orderApi({action:'my_orders'});
      const order=(d.orders||[]).find(o=>o.status==='amendment_required');
      const x=ensureAlert();
      if(order){if(String(order.id)!==shownOrderId||x.classList.contains('hide'))showAmend(order)}
      else{x.classList.add('hide');shownOrderId=''}
    }catch{}
  }

  window.dextersCollectionAmend={applyOutages,applyOutagesToCategories,showAmend,submit:amendApi};
  setTimeout(()=>{applyOutages();poll()},1200);
  // Keep customer amendment status responsive, but do not rebuild the full menu every 5 seconds.
  setInterval(poll,5000);
  setInterval(applyOutages,60000);
})();

(function(){
  const STORE='dexters-collection-basket-v3';
  const HIDDEN_ADDONS=new Set([
    'extra chicken','extra beef','king prawns','fried egg','cheese','extra crispy onions','extra spring onions','extra sauce',
    'drink upgrade','extra pineapple','toasted coconut','white chocolate sauce','alcohol-free rum drizzle','extra whipped cream',
    'cream foam','sour boost','fruit chunks','extra syrup','vanilla syrup','caramel syrup','hazelnut syrup','extra espresso shot','oat milk','almond milk'
  ]);
  const state={lines:[],current:null,groups:new Map(),selected:new Map(),modifierReady:false,modifierLoading:false,editing:null,owner:'',importBusy:false,importDone:false,placing:false,amendOrderId:null};
  const byId=id=>document.getElementById(id);
  const esc2=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>{const m=String(v||'').replace(',','.').match(/£?\s*(\d+(?:\.\d{1,2})?)/);return m?Number(m[1]):0};
  const priceLabel=v=>Number(v||0)>0?'+£'+Number(v).toFixed(2):'Included';
  function loadSaved(){state.lines=[];if(!state.owner)return;try{const x=JSON.parse(sessionStorage.getItem(STORE+':'+state.owner)||'[]');if(Array.isArray(x))state.lines=x}catch(e){state.lines=[]}}
  function save(){if(!state.owner)return;try{sessionStorage.setItem(STORE+':'+state.owner,JSON.stringify(state.lines))}catch(e){}}
  function findItem(k){try{for(const c of categories||[])for(const i of c.items||[])if(String(i.id||i.name)===String(k))return {...i,category_id:c.id||null,category_name:c.name||''}}catch(e){}return null}
  function itemLabel(item){const current=findItem(item.id);const category=String(current?.category_name||item.category_name||'').trim();return category?category+' — '+item.name:item.name}
  function groupsFor(item){return state.groups.get(String(item?.id||''))||[]}
  function isTenderItem(item){const c=String(item?.category_name||'').trim().toLowerCase();return c==='chicken tenders'||c==='inferno chicken tenders'}
  function tenderDipLimit(item,groups,selections){if(!isTenderItem(item))return null;const pg=groups.find(g=>String(g.name||'').trim().toLowerCase()==='choose your portion');if(!pg)return null;const ids=selections.get(pg.id)||new Set();const po=pg.options.find(o=>ids.has(o.id));const m=String(po?.name||'').match(/^\s*(4|6|10)\b/);if(!m)return null;return m[1]==='4'?1:m[1]==='6'?2:3}
  function selectionMapForLine(line){const m=new Map();for(const x of line?.modifiers||[])m.set(String(x.group_id),new Set((x.option_ids||[]).map(String)));return m}
  function normalizeTenderDips(item,groups){const limit=tenderDipLimit(item,groups,state.selected);if(limit==null)return;const dg=groups.find(g=>String(g.name||'').trim().toLowerCase()==='choose included dips');if(!dg)return;const s=selectedSet(dg.id);if(s.size<=limit)return;const keep=[...s].slice(0,limit);state.selected.set(dg.id,new Set(keep))}
  function isHiddenAddon(c,i){const n=String(i?.name||'').toLowerCase();const cat=String(c?.name||'').toLowerCase();if(cat==='rice bowls'&&['extra chicken','extra beef','king prawns','fried egg','cheese','extra crispy onions','extra spring onions','extra sauce'].includes(n))return true;if(cat==='reaper box'&&n==='drink upgrade')return true;if(cat==='waffles'&&['extra pineapple','toasted coconut','white chocolate sauce','alcohol-free rum drizzle','extra whipped cream'].includes(n))return true;if(cat==='dirty soda bar'&&['cream foam','sour boost','fruit chunks','extra syrup'].includes(n))return true;if(cat==='coffee'&&['vanilla syrup','caramel syrup','hazelnut syrup','extra espresso shot','oat milk','almond milk'].includes(n))return true;return false}
  async function loadModifierData(){
    if(state.modifierLoading)return;
    state.modifierLoading=true;state.modifierReady=false;
    renderMenu();
    try{
      // The public RPC is capped per request. Read every page in a stable,
      // unique order before making any item available for ordering.
      const rows=[],pageSize=500;
      for(let offset=0;;){
        const r=await fetch(U+'/rest/v1/rpc/loyalty_modifier_public?order=menu_item_id.asc,group_id.asc,option_id.asc&limit='+pageSize+'&offset='+offset,{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:'{}'});
        if(!r.ok)throw new Error('modifier fetch failed');
        const page=await r.json();
        if(!Array.isArray(page))throw new Error('invalid modifier response');
        if(!page.length)break;
        rows.push(...page);offset+=page.length;
      }
      const items=new Map();
      for(const row of(Array.isArray(rows)?rows:[])){
        const itemId=String(row.menu_item_id),gid=String(row.group_id);let arr=items.get(itemId);if(!arr){arr=[];items.set(itemId,arr)}
        let g=arr.find(x=>x.id===gid);if(!g){g={id:gid,name:row.group_name,type:row.selection_type,required:!!row.required,min:Number(row.min_select||0),max:row.max_select==null?null:Number(row.max_select),sort:Number(row.group_sort_order||0),options:[]};arr.push(g)}
        g.options.push({id:String(row.option_id),name:row.option_name,price:Number(row.price_delta||0),sort:Number(row.option_sort_order||0)});
      }
      for(const arr of items.values()){arr.sort((a,b)=>a.sort-b.sort);for(const g of arr)g.options.sort((a,b)=>a.sort-b.sort)}
      state.groups=items;state.modifierReady=true;
    }catch(e){console.warn('Dexters menu choices could not be loaded',e);state.groups=new Map();state.modifierReady=false}
    finally{state.modifierLoading=false;renderMenu()}
  }
  function choicesReady(){
    if(state.modifierReady)return true;
    byId('msg').innerHTML='<div class="status bad">Please wait for the menu choices to load. If loading failed, tap Retry menu choices above.</div>';
    return false;
  }
  function missingChoice(line){
    const groups=groupsFor(line),sels=selectionMapForLine(line),dipLimit=tenderDipLimit(line,groups,sels);
    for(const g of groups){
      const ids=sels.get(g.id)||new Set();
      const valid=g.options.filter(o=>ids.has(o.id)).length;
      if(valid<Math.max(g.required?1:0,g.min||0)||valid!==(ids.size)||valid>(g.max??Infinity))return g.name;
      if(dipLimit!=null&&String(g.name||'').trim().toLowerCase()==='choose included dips'&&valid!==dipLimit)return g.name;
    }
    return '';
  }
  function ensureUi(){
    if(byId('liveModifierModal'))return;
    const style=document.createElement('style');style.id='liveModifierStyle';style.textContent='.live-custom-btn{border:0;border-radius:10px;padding:10px 12px;font-weight:900;background:#ffd43b;color:#08101d}.live-mod-modal{position:fixed;inset:0;background:#000b;display:grid;place-items:end center;z-index:80}.live-mod-modal.hide{display:none!important}.live-mod-sheet{width:min(700px,100%);max-height:88vh;overflow:auto;background:#132038;border-radius:22px 22px 0 0;padding:18px;box-sizing:border-box}.live-mod-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.live-mod-close{border:0;border-radius:10px;padding:10px 12px;background:#243a5e;color:#fff;font-weight:900}.live-mod-group{margin-top:16px;padding-top:12px;border-top:1px solid #ffffff18}.live-mod-group h3{margin:0 0 4px}.live-required{color:#ffd43b;font-size:12px;font-weight:900}.live-opt{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid #ffffff12}.live-opt label{display:flex;gap:9px;align-items:center;flex:1}.live-opt input{width:20px;height:20px}.live-price{font-weight:800;color:#9ff3c5}.live-mod-summary{font-size:13px;color:#cbd5e1;margin-top:14px}.live-mod-error{font-size:13px;color:#ffc1cb;margin-top:10px}.live-mod-add{width:100%;border:0;border-radius:12px;padding:14px;background:#ffd43b;color:#08101d;font-weight:900;margin-top:14px}.review-mods{font-size:12px;color:#9ff3c5;margin-top:4px}.review-standard{font-size:12px;color:#aab4c3;margin-top:4px}';document.head.appendChild(style);
    const modal=document.createElement('div');modal.id='liveModifierModal';modal.className='live-mod-modal hide';modal.innerHTML='<div class="live-mod-sheet"><div class="live-mod-top"><div><h2 id="liveModName" style="margin:0"></h2><div id="liveModPrice" class="item-price"></div></div><button type="button" id="liveModClose" class="live-mod-close">Close</button></div><p id="liveModDesc" class="item-desc"></p><div id="liveModGroups"></div><div id="liveModSummary" class="live-mod-summary">Choose your options.</div><div id="liveModError" class="live-mod-error"></div><button type="button" id="liveModAdd" class="live-mod-add">Add to order</button></div>';document.body.appendChild(modal);
    byId('liveModClose').onclick=()=>modal.classList.add('hide');modal.onclick=e=>{if(e.target===modal)modal.classList.add('hide')};byId('liveModAdd').onclick=addCurrent;
  }
  function openCustom(k,editing=null){if(state.placing)return;if(!choicesReady())return;ensureUi();const item=findItem(k);if(!item||item.in_stock===false)return;state.current=item;state.editing=editing;state.selected=new Map();if(editing!==null)for(const m of state.lines[editing]?.modifiers||[]){const g=groupsFor(item).find(g=>g.id===m.group_id);if(g)state.selected.set(g.id,new Set(m.option_ids.filter(id=>g.options.some(o=>o.id===id))))}byId('liveModName').textContent=itemLabel(item);byId('liveModPrice').textContent=item.price||'';byId('liveModDesc').textContent=item.description||'';byId('liveModError').textContent=editing===null?'':(state.lines[editing]?.reorderIssue||'Review your saved choices.');byId('liveModAdd').textContent=editing===null?'Add to order':'Save choices';normalizeTenderDips(item,groupsFor(item));drawGroups();byId('liveModifierModal').classList.remove('hide')}
  function selectedSet(gid){let s=state.selected.get(gid);if(!s){s=new Set();state.selected.set(gid,s)}return s}
  function drawGroups(){
    const root=byId('liveModGroups');if(!root||!state.current)return;const groups=groupsFor(state.current),dipLimit=tenderDipLimit(state.current,groups,state.selected);root.innerHTML=groups.map(g=>{const dipGroup=String(g.name||'').trim().toLowerCase()==='choose included dips'&&dipLimit!=null;const title=dipGroup?g.name+' ('+dipLimit+' included)':g.name;return '<section class="live-mod-group"><h3>'+esc2(title)+' '+((g.required||g.min>0)?'<span class="live-required">REQUIRED</span>':'')+'</h3>'+g.options.map(o=>{const on=(state.selected.get(g.id)||new Set()).has(o.id);const typ=g.type==='single'?'radio':'checkbox';return '<div class="live-opt"><label><input type="'+typ+'" name="mg-'+esc2(g.id)+'" data-gid="'+esc2(g.id)+'" data-oid="'+esc2(o.id)+'" '+(on?'checked':'')+'><span>'+esc2(o.name)+'</span></label><span class="live-price">'+priceLabel(o.price)+'</span></div>'}).join('')+'</section>'}).join('');
    root.querySelectorAll('input[data-gid]').forEach(inp=>inp.onchange=()=>{const gid=inp.dataset.gid,oid=inp.dataset.oid,g=groups.find(x=>x.id===gid);const s=selectedSet(gid);if(g?.type==='single'){s.clear();if(inp.checked)s.add(oid);if(String(g.name||'').trim().toLowerCase()==='choose your portion')normalizeTenderDips(state.current,groups)}else{const isIncluded=String(g?.name||'').trim().toLowerCase()==='choose included dips';const limit=tenderDipLimit(state.current,groups,state.selected);if(inp.checked&&isIncluded&&limit!=null&&s.size>=limit){if(limit===1){s.clear();s.add(oid);byId('liveModError').textContent='This portion includes 1 dip. Use Extra dips for any additional sauces.'}else{inp.checked=false;byId('liveModError').textContent='This portion includes '+limit+' dips. Use Extra dips for any additional sauces.'}}else{inp.checked?s.add(oid):s.delete(oid);if(isIncluded)byId('liveModError').textContent=''}}drawGroups()});
    let extra=0;const labels=[];for(const g of groups){const ids=state.selected.get(g.id)||new Set();const names=[];for(const o of g.options)if(ids.has(o.id)){names.push(o.name);extra+=o.price}if(names.length)labels.push(g.name+': '+names.join(', '))}byId('liveModSummary').textContent=(labels.length?labels.join(' · '):'No options selected')+' · Total £'+(money(state.current.price)+extra).toFixed(2);
  }
  function addCurrent(){if(state.placing)return;if(!choicesReady()||!state.current)return;const groups=groupsFor(state.current),dipLimit=tenderDipLimit(state.current,groups,state.selected);for(const g of groups){const n=(state.selected.get(g.id)||new Set()).size;const min=Math.max(g.required?1:0,g.min||0),max=g.max==null?999:g.max;if(n<min){byId('liveModError').textContent='Please choose '+g.name+'.';return}if(n>max){byId('liveModError').textContent='Please reduce your choices for '+g.name+'.';return}if(dipLimit!=null&&String(g.name||'').trim().toLowerCase()==='choose included dips'&&n!==dipLimit){byId('liveModError').textContent='This portion includes exactly '+dipLimit+' dip'+(dipLimit===1?'':'s')+'. Choose any extra sauces under Extra dips.';return}}
    const modifiers=[];let extra=0;const labels=[];for(const g of groups){const ids=[...(state.selected.get(g.id)||new Set())];if(!ids.length)continue;const chosen=g.options.filter(o=>ids.includes(o.id));modifiers.push({group_id:g.id,option_ids:ids});extra+=chosen.reduce((a,o)=>a+o.price,0);labels.push(g.name+': '+chosen.map(o=>o.name).join(', '))}
    const nextLine={id:state.current.id,name:state.current.name,category_id:state.current.category_id,category_name:state.current.category_name,price:state.current.price||'',qty:1,modifiers,modifierLabels:labels,modifierTotal:extra};if(state.editing===null)state.lines.push(nextLine);else state.lines[state.editing]=nextLine;state.editing=null;save();byId('liveModifierModal').classList.add('hide');try{cart={}}catch(e){}renderMenu();renderReview();
  }
  renderMenu=function(){const q=(byId('search')?.value||'').toLowerCase().trim();let html=state.modifierReady?'':state.modifierLoading?'<div class="status">Loading menu choices…</div>':'<div class="status bad">Menu choices could not load. <button type="button" id="retryMenuChoices">Retry menu choices</button></div>';for(const c of categories||[]){const items=(c.items||[]).filter(i=>!isHiddenAddon(c,i)).filter(i=>String(i.name||'').toLowerCase()!=='hot & sour soup').filter(i=>!q||(`${c.name} ${i.name} ${i.description||''}`).toLowerCase().includes(q));if(!items.length)continue;html+=`<div class="menu-cat ${q?'open':''}"><button class="menu-head" type="button"><span>${esc(c.name)} <small class="tiny">(${items.length})</small></span><span>▾</span></button><div class="menu-body">${items.map(i=>{const canCustom=groupsFor(i).length>0,count=state.lines.filter(x=>String(x.id)===String(i.id)).length;let control;if(i.in_stock===false)control='<span class="sold">OUT OF STOCK</span>';else if(!state.modifierReady)control='<button class="qbtn" disabled>Loading choices</button>';else if(canCustom)control=`<button class="live-custom-btn" data-live-custom="${esc(i.id||i.name)}">${count?'CUSTOMISE +':'CUSTOMISE'}</button>`;else control=`<button class="qbtn" data-live-standard="${esc(i.id||i.name)}">${count?'ADD +':'ADD'}</button>`;return `<div class="item ${i.in_stock===false?'out':''}"><div class="item-main"><div class="item-name">${esc(i.name)}</div>${i.description?`<div class="item-desc">${esc(i.description)}</div>`:''}<div class="item-price">${esc(i.price||'')}</div>${count?`<div class="tiny">${count} in your order</div>`:''}</div>${control}</div>`}).join('')}</div></div>`}byId('menu').innerHTML=html||'<div class="menu-empty">No menu items match your search.</div>';if(byId('retryMenuChoices'))byId('retryMenuChoices').onclick=async()=>{await loadModifierData();await importReorder()};byId('menu').querySelectorAll('.menu-head').forEach(b=>b.onclick=()=>b.parentElement.classList.toggle('open'));byId('menu').querySelectorAll('[data-live-custom]').forEach(b=>b.onclick=()=>openCustom(b.dataset.liveCustom));byId('menu').querySelectorAll('[data-live-standard]').forEach(b=>b.onclick=()=>{if(state.placing)return;if(!choicesReady())return;const i=findItem(b.dataset.liveStandard);if(i){state.lines.push({id:i.id,name:i.name,category_id:i.category_id,category_name:i.category_name,price:i.price||'',qty:1,modifiers:[],modifierLabels:[],modifierTotal:0});save()}renderMenu();renderReview()})};
  function renderReview(){const root=byId('orderReviewList'),tot=byId('orderReviewTotal'),cnt=byId('orderReviewCount');if(!root)return;let sum=0;state.lines.forEach(x=>sum+=money(x.price)+Number(x.modifierTotal||0));root.innerHTML=state.lines.length?state.lines.map((x,idx)=>'<div class="review-row"><div><div class="review-name">'+esc2(itemLabel(x))+'</div><div class="review-meta">Qty 1 × '+esc2(x.price||'')+'</div>'+((x.modifierLabels||[]).length?'<div class="review-mods">'+x.modifierLabels.map(esc2).join('<br>')+'</div>':'<div class="review-standard">Standard build</div>')+'</div><div class="review-right"><div class="review-line-total">£'+(money(x.price)+Number(x.modifierTotal||0)).toFixed(2)+'</div>'+((x.reorderIssue||x.reorderNote)?'<div class="review-meta" role="status">'+esc2(x.reorderIssue||x.reorderNote)+'</div>':'')+'<button type="button" class="live-custom-btn" data-live-edit="'+idx+'">Check choices</button><button type="button" class="review-remove" data-live-remove="'+idx+'">Remove</button></div></div>').join(''):'<div class="review-empty">Your order is empty. Add items from the menu above.</div>';root.querySelectorAll('[data-live-edit]').forEach(b=>b.onclick=()=>openCustom(state.lines[Number(b.dataset.liveEdit)].id,Number(b.dataset.liveEdit)));root.querySelectorAll('[data-live-remove]').forEach(b=>b.onclick=()=>{if(state.placing)return;state.lines.splice(Number(b.dataset.liveRemove),1);save();renderMenu();renderReview()});if(tot)tot.textContent='£'+sum.toFixed(2);if(cnt)cnt.textContent=state.lines.length+' item'+(state.lines.length===1?'':'s')}
  window.renderOrderReview=renderReview;
  window.DexterCollectionBasket={
    loadAmendment(order){
      if(!order||!Array.isArray(order.items))throw Error('This order could not be loaded for amendment.');
      const blocked=new Set((Array.isArray(order.amendment_items)?order.amendment_items:[]).map(String));
      const kept=order.items.filter(x=>!blocked.has(String(x.id||'')));
      state.lines=window.DexterReorder.restore(kept,reorderMenu(),state.groups);
      state.amendOrderId=String(order.id||'');
      save();renderMenu();renderReview();
      if(byId('placeBtn'))byId('placeBtn').textContent='Send amended order';
      byId('orderReviewCard')?.scrollIntoView({behavior:'smooth',block:'start'});
      return state.lines.length;
    },
    cancelAmendment(){
      state.amendOrderId=null;state.lines=[];save();renderMenu();renderReview();
      if(byId('placeBtn'))byId('placeBtn').textContent='Confirm & Place Order';
    }
  };
  async function placeModified(){if(state.placing||state.importBusy)return;if(!choicesReady())return;if(!state.owner){byId('msg').textContent='Please sign in before placing an order.';return}if(state.lines.length>40){byId('msg').textContent='Please keep your order to 40 items or fewer.';return}state.placing=true;const placingOwner=state.owner;try{await freshMenu();await loadModifierData();if(state.owner!==placingOwner||!choicesReady())return;let changed=false;for(let idx=0;idx<state.lines.length;idx++){const check=window.DexterReorder.validate(state.lines[idx],reorderMenu(),state.groups);if(check.issues.length||state.lines[idx].reorderIssue){state.lines[idx].reorderIssue=state.lines[idx].reorderIssue||check.issues.join(' ');save();renderReview();byId('msg').textContent='Check the marked choices or remove unavailable items before ordering.';return}if(check.changed){state.lines[idx]={...check.line,reorderNote:'Price updated. Please review the new total.'};changed=true}}if(changed){save();renderReview();byId('msg').textContent='Prices changed. Review the updated total, then confirm again.';return}for(const line of state.lines){const missing=missingChoice(line);if(missing){byId('msg').innerHTML='<div class="status bad">'+esc2(itemLabel(line))+' needs '+esc2(missing)+'. Remove this item and add it again to choose your options.</div>';return}}const name=byId('customerName').value.trim(),phone=byId('customerPhone').value.trim();if(!name){byId('msg').innerHTML='<div class="status bad">Please enter your full name.</div>';return}if(phone.replace(/\D/g,'').length<7){byId('msg').innerHTML='<div class="status bad">Please enter a valid phone number.</div>';return}if(!state.lines.length){byId('msg').innerHTML='<div class="status bad">Please add at least one available item.</div>';return}const items=state.lines.map(x=>({id:x.id,name:x.name,category_name:x.category_name||'',qty:1,modifiers:x.modifiers||[],removed:[],modifier_total:Number(x.modifierTotal||0)}));try{
      let d;
      if(state.amendOrderId){
        const t=(await sb.auth.getSession()).data.session?.access_token||'';
        const r=await fetch(U+'/functions/v1/collection-order-amend-test-api',{method:'POST',headers:{apikey:K,Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({action:'submit_amendment',id:state.amendOrderId,items})});
        d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Could not send your amended order.');
        if(state.owner!==placingOwner)return;
        byId('msg').innerHTML='<div class="status ok">Amended order sent to Dexter’s.</div>';
        state.amendOrderId=null;
      }else{
        d=await ownedApi({action:'create',items,collection_time:byId('collectionTime').value,order_notes:byId('notes').value,customer_name:name,customer_phone:phone},placingOwner);
        if(state.owner!==placingOwner)return;
        byId('msg').innerHTML='<div class="status ok">Order #'+d.order.order_number+' sent to Dexter’s.</div>';
      }
      state.lines=[];save();try{cart={}}catch(e){}renderMenu();renderReview();if(byId('placeBtn'))byId('placeBtn').textContent='Confirm & Place Order';loadOrders()}catch(e){byId('msg').innerHTML='<div class="status bad">'+esc2(e.message)+'</div>';try{loadMenu()}catch(_){}}}catch(e){if(state.owner===placingOwner)byId('msg').textContent=e.message||'Could not refresh the menu. Please try again.'}finally{state.placing=false}}

  function reorderMenu(){return categories.map(c=>({...c,items:(c.items||[]).filter(i=>!isHiddenAddon(c,i)&&String(i.name||'').toLowerCase()!=='hot & sour soup')}))}
  async function freshMenu(){const r=await fetch(U+'/rest/v1/rpc/loyalty_menu_public',{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('Could not check the current menu. Please try again.');const d=await r.json();if(!Array.isArray(d))throw Error('The menu could not be checked.');categories=d;if(window.dextersCollectionAmend?.applyOutagesToCategories)await window.dextersCollectionAmend.applyOutagesToCategories(categories);renderMenu()}
  async function ownedApi(body,owner){const {data}=await sb.auth.getSession();if(!data.session||data.session.user.id!==owner||state.owner!==owner)throw Error('Your account changed. Please review your basket again.');const r=await fetch(U+'/functions/v1/collection-orders-api',{method:'POST',headers:{apikey:K,Authorization:'Bearer '+data.session.access_token,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Could not send your order.');return d}
  async function importReorder(){
    const params=new URLSearchParams(location.search),id=params.get('reorder');
    if(!id||state.importDone||state.importBusy||!state.modifierReady)return;
    let notice=byId('reorderNotice');if(!notice){notice=document.createElement('div');notice.id='reorderNotice';notice.className='status';byId('orderReviewCard').before(notice)}
    notice.textContent='Loading your previous order for review…';state.importBusy=true;
    const owner=state.owner;
    try{
      if(!owner)throw Error('Sign in to restore your own previous orders.');
      const d=await api({action:'my_orders'});await freshMenu();
      if(owner!==state.owner)throw Error('Your account changed. Open Order Again from your home screen.');
      const order=(d.orders||[]).find(o=>String(o.id)===id);if(!order)throw Error('This order is not available in your recent order history.');
      let items=order.items;
      if(params.has('usual')){const raw=params.get('usual');if(!/^\d+$/.test(raw)||!items?.[Number(raw)])throw Error('This saved item could not be found.');items=[{...items[Number(raw)],qty:1}]}
      const lines=window.DexterReorder.restore(items,reorderMenu(),state.groups);
      if(lines.length+state.lines.length>40)throw Error('Your existing basket and this order exceed 40 items. Remove some items before trying again.');
      const previous=state.lines.length;state.lines.push(...lines);save();state.importDone=true;
      const url=new URL(location.href);url.searchParams.delete('reorder');url.searchParams.delete('usual');history.replaceState(null,'',url.pathname+url.search+url.hash);
      notice.textContent=lines.length+' previous item'+(lines.length===1?'':'s')+' added'+(previous?' to your existing basket':'')+'. Check every item, current price and choice before confirming. Nothing has been sent to the kitchen.';
      renderMenu();renderReview();notice.scrollIntoView({block:'start'});
    }catch(e){notice.textContent=e.message+' ';const retry=document.createElement('button');retry.type='button';retry.className='live-custom-btn';retry.textContent='Retry previous order';retry.onclick=importReorder;notice.append(retry)}
    finally{state.importBusy=false}
  }
  async function init(){ensureUi();const {data}=await sb.auth.getSession();state.owner=data.session?.user?.id||'';loadSaved();sb.auth.onAuthStateChange((_event,session)=>{const owner=session?.user?.id||'';if(owner!==state.owner){state.owner=owner;for(const id of ['customerName','customerPhone','notes'])if(byId(id))byId(id).value='';if(byId('orders'))byId('orders').textContent='';if(byId('msg'))byId('msg').textContent='';if(byId('reorderNotice'))byId('reorderNotice').textContent='';state.current=null;state.editing=null;byId('liveModifierModal').classList.add('hide');loadSaved();renderMenu();renderReview()}});try{cart={}}catch(e){}if(byId('search'))byId('search').oninput=renderMenu;if(byId('placeBtn')){byId('placeBtn').onclick=placeModified;byId('placeBtn').textContent='Confirm & Place Order'}renderMenu();renderReview();await loadModifierData();await importReorder()}
  setTimeout(()=>init().catch(e=>console.warn('modifier init',e)),0);setTimeout(()=>{if(!state.modifierReady)loadModifierData().then(renderMenu).catch(()=>{})},1200);
})();
